target.css:
:root {
  --ink: #243238;
  --paper: #fffdf7;
  --line: #cbd7d2;
  --pine: #174e4b;
  --mint: #dcefe7;
  --ember: #d65d43;
  --sun: #f3c75d;
  --slate: #68787d;
}

* {
  box-sizing: border-box;
}

.watch-card {
  width: 500px;
  height: 282px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 14px;
  overflow: hidden;
  color: var(--ink);
  background: var(--paper);
  border: 2px solid var(--pine);
  border-radius: 18px 18px 8px 8px;
}

.watch-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 9px;
  border-bottom: 1px solid var(--line);
}

.watch-head section,
.watch-head h2,
.eyebrow,
.alert-state,
.metric,
.section-label,
.wind-top strong {
  margin: 0;
}

.eyebrow,
.section-label {
  color: var(--slate);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1.1px;
  line-height: 1.2;
  text-transform: uppercase;
}

.watch-head h2 {
  margin-top: 3px;
  color: var(--pine);
  font-size: 21px;
  font-weight: 800;
  line-height: 1;
}

.alert-state {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 9px;
  color: var(--ember);
  background: var(--mint);
  border-radius: 999px;
  font-size: 11px;
  font-weight: 800;
}

.alert-state::before {
  width: 7px;
  height: 7px;
  content: "";
  background: var(--ember);
  border-radius: 50%;
}

.metrics {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  background: var(--mint);
  border: 1px solid var(--line);
  border-radius: 8px;
}

.metric {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 10px;
}

.metric + .metric {
  border-left: 1px solid var(--line);
}

.metric span {
  color: var(--slate);
  font-size: 11px;
  font-weight: 700;
}

.metric strong {
  color: var(--pine);
  font-size: 18px;
  line-height: 1;
}

.metric em,
.wind-top em {
  color: var(--slate);
  font-size: 10px;
  font-style: normal;
  font-weight: 700;
}

.watch-body {
  display: grid;
  grid-template-columns: 1.35fr 1fr;
  gap: 10px;
  min-height: 0;
  flex: 1;
}

.activity,
.wind-panel {
  padding: 9px 10px;
  border: 1px solid var(--line);
  border-radius: 8px;
}

.route {
  display: grid;
  gap: 2px;
  margin: 6px 0 0;
  padding: 0;
  list-style: none;
}

.route li {
  display: grid;
  grid-template-columns: 38px 1fr auto;
  align-items: center;
  gap: 5px;
  min-height: 20px;
  color: var(--ink);
  border-bottom: 1px solid var(--mint);
  font-size: 11px;
  line-height: 1.1;
}

.route li:last-child {
  border-bottom: 0;
}

.route time {
  color: var(--slate);
  font-size: 10px;
  font-weight: 700;
}

.route b {
  padding: 3px 5px;
  color: var(--pine);
  background: var(--sun);
  border-radius: 3px;
  font-size: 8px;
  letter-spacing: .4px;
}

.wind-panel {
  display: flex;
  flex-direction: column;
  background: var(--pine);
  border-color: var(--pine);
}

.wind-panel .section-label {
  color: var(--mint);
}

.wind-top {
  display: flex;
  align-items: center;
  gap: 8px;
  flex: 1;
}

.compass {
  display: grid;
  width: 42px;
  height: 42px;
  place-items: center;
  color: var(--pine);
  background: var(--sun);
  border: 3px solid var(--paper);
  border-radius: 50%;
  font-size: 12px;
  font-weight: 900;
}

.wind-top strong {
  color: var(--paper);
  font-size: 12px;
  line-height: 1.15;
}

.wind-top em {
  color: var(--mint);
}

button {
  width: 100%;
  padding: 6px 8px;
  color: var(--pine);
  background: var(--paper);
  border: 0;
  border-radius: 4px;
  font-size: 11px;
  font-weight: 800;
}

